entries[46106] = { ["name"] = "Wunderheilbinokel XT68", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nWunderheilbinokel XT40 , Urwasser (4), Urmana (8), Urnether (4)\nOptionale Reagenzien:\n[] (#50)\nBeute von:\nDer Sonnenbrunnen\n\nWunderheilbinokel XT68\nWird beim Anlegen gebunden\nKopf Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]+5 Ausdauer\n+ 3 Vielseitigkeit\n\nMetasockel\nPrismatischer Sockel\nSockelbonus: + 2 Zaubermacht\n\nHaltbarkeit 100 / 100\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen. (3 Sek. Abklingzeit)\n27\nBenötigt Ingenieurskunst der Scherbenwelt\n(1)" }
entries[46107] = { ["name"] = "Gerechtomatbrille 3000", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nGerechtomatbrille 2000 , Urleben (8), Urmana (8), Urerde (8), Urnether (4)\nOptionale Reagenzien:\n[] (#50)\nBeute von:\nDer Sonnenbrunnen\n\nGerechtomatbrille 3000\nWird beim Anlegen gebunden\nKopf Platte\n11 Rüstung\n+4 [Stärke oder Intelligenz]+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\n\nMetasockel\nPrismatischer Sockel\nSockelbonus: + 2 kritischer Trefferwert\n\nHaltbarkeit 100 / 100\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen. (3 Sek. Abklingzeit)\n27\nBenötigt Ingenieurskunst der Scherbenwelt\n(1)" }
